```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Platform-approved state-rw grant: record the input this call received.
        state_rw::put("last-input", &feed_url);

        let now = wall_clock::now();

        // One permitted fetch. A transport failure is a value, not a trap;
        // it contributes zero characters to the report.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let notified = notifier::notify("digest");

        // The contract requires notified == true for every produced output.
        // If the notification was refused, produce no output at all.
        assert!(notified, "notifier refused the digest notification");

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
